// WF-P1 "Plan searches" (Code node, Run Once for All Items).
// SOP section 4, step 1: "[niche] podcast …" searches across 18 niches. Each run takes the next
// `searches_per_run` searches from the full list (rotating by the hour), so over a day every niche is covered.
// One YouTube search costs 100 of the free 10,000 daily quota units: 20 searches a run x 2 runs = 4,000.

const cfg = $('Settings').first().json
const NICHES = [
  'business', 'startups', 'finance', 'fitness', 'health', 'mental health', 'tech', 'AI', 'marketing', 'true crime',
  'comedy', 'sports', 'parenting', 'real estate', 'creator economy', 'career', 'faith', 'education',
]
const GUESTS = ['founder', 'coach', 'doctor', 'author', 'CEO', 'expert']
const TEMPLATES = [
  n => `${n} podcast episode`,
  n => `${n} podcast full episode ${new Date().getFullYear()}`,
  n => `${n} podcast interview`,
  (n, i) => `${n} podcast ep ${8 + (i % 20)}`, // small shows often have low episode numbers
  (n, i) => `${n} podcast with ${GUESTS[i % GUESTS.length]}`,
  n => `new podcast ${n} first season`,
]

const all = []
TEMPLATES.forEach((t, ti) => NICHES.forEach((n, ni) => all.push({ niche: n, q: t(n, ni + ti) })))

const per = Math.max(1, Math.min(all.length, Number(cfg.searches_per_run) || 20))
// Different slice every run: hours since epoch x per, wrapped around the list.
const start = (Math.floor(Date.now() / 3600000) * per) % all.length
const picked = Array.from({ length: per }, (_, i) => all[(start + i) % all.length])

// "Upload date: this month" from the SOP tip; videoDuration=long (> 20 min) is the "Duration" filter.
const publishedAfter = new Date(Date.now() - 30 * 86400000).toISOString().replace(/\.\d{3}Z$/, 'Z')
return picked.map(p => ({ json: { ...p, publishedAfter } }))

// WF-P1 "Collect channels" (Code node, Run Once for All Items).
// Input: one YouTube search.list response per planned search. Output: ONE item { rows, searched, failed }
// where rows are new podcast_leads (stage 'found'); WF-P2 checks each one against the SOP.

const plans = $('Plan searches').all().map(i => i.json)
const planFor = i => {
  try {
    return $('Plan searches').itemMatching(i).json
  } catch {
    return plans[i] || {}
  }
}
const errorText = err => {
  const t = String((err && err.message) || err || 'unknown error')
  return (t.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/) || [])[1] || t
}

// Obvious big networks / brands: never small shows (SOP: skip network-owned podcasts).
const BIG = /\b(TED|NPR|BBC|CNN|Fox|NBC|CBS|ABC News|iHeart|Spotify|Wondery|Bloomberg|Forbes|CNBC|Barstool|PBD|Joe Rogan|Lex Fridman|Diary Of A CEO|Huberman|Valuetainment)\b/i

const seen = new Map()
const failed = []
let searched = 0
$input.all().forEach((item, i) => {
  const plan = planFor(i)
  const res = item.json || {}
  if (res.error || !Array.isArray(res.items)) {
    failed.push({ message: `YouTube search "${plan.q}": ${errorText(res.error || 'no results field')}`.slice(0, 300) })
    return
  }
  searched++
  for (const v of res.items) {
    const s = v && v.snippet
    const channelId = s && s.channelId
    if (!channelId || seen.has(channelId)) continue
    if (BIG.test(s.channelTitle || '')) continue
    seen.set(channelId, {
      youtube_channel_id: channelId,
      youtube_channel_url: `https://www.youtube.com/channel/${channelId}`,
      podcast_name: String(s.channelTitle || '').slice(0, 200) || null,
      niche: plan.niche || null,
      source_query: plan.q || null,
      stage: 'found',
      status: 'New',
    })
  }
})

return [{ json: { rows: [...seen.values()], searched, failed } }]

// WF-P1 "Run summary" (Code node, Run Once for All Items). One workflow_logs row per run.
const cfg = $('Config').first().json
const c = $('Collect channels').first().json
// The insert returns only channels that were new (ones already in podcast_leads are skipped by the database).
const inserted = $input.all().filter(i => i.json && i.json.id).length
const failed = c.failed || []
return [{
  json: {
    workflow_name: 'WF-P1-PodcastFind',
    status: c.searched === 0 && failed.length ? 'failed' : 'success',
    leads_scraped: inserted,
    leads_skipped: Math.max(0, (c.rows || []).length - inserted),
    leads_scored: 0,
    emails_sent: 0,
    replies_detected: 0,
    errors: failed.length ? failed : null,
    started_at: cfg.started_at,
    finished_at: new Date().toISOString(),
  },
}]

// Podcast "Settings" (Code node, Run Once for All Items).
// Starts from this workflow's Config node, then applies the dashboard settings saved in Supabase:
//   settings.key = 'outreach' -> shared with the startup pipeline: STOP ALL, timezone, send window, signature
//   settings.key = 'podcast'  -> podcast only: daily limit (10), subscriber range, searches per run, sheet URL, …
// Anything missing or invalid keeps the Config value.
const cfg = { ...$('Config').first().json }
const rows = $input.all().map(i => i.json).filter(r => r && r.key)
const valueOf = key => {
  const r = rows.find(x => x.key === key)
  return r && r.value && typeof r.value === 'object' && !Array.isArray(r.value) ? r.value : {}
}

const num = (min, max) => v => {
  const n = Number(v)
  return v !== '' && v !== null && Number.isFinite(n) && n >= min && n <= max ? Math.round(n) : undefined
}
const bool = v => (typeof v === 'boolean' ? v : undefined)
const text = v => (typeof v === 'string' && v.trim() ? v.trim().slice(0, 300) : undefined)
const days = v => {
  const list = (Array.isArray(v) ? v : String(v).split(',')).map(Number).filter(n => Number.isInteger(n) && n > 0 && n <= 90)
  return list.length ? list.join(',') : '0'
}
const tz = v => {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: String(v) })
    return String(v)
  } catch {
    return undefined
  }
}

// [dashboard key, Config key, rule]
const SHARED = [
  ['paused', 'paused', bool],
  ['timezone', 'timezone', tz],
  ['send_window_start', 'send_window_start', num(0, 23)],
  ['send_window_end', 'send_window_end', num(1, 24)],
  ['send_on_weekends', 'send_on_weekends', bool],
  ['from_name', 'from_name', text],
  ['sign_off', 'sign_off', text],
  ['signature_name', 'signature_name', text],
  ['company_name', 'company_name', text],
  ['website', 'website', text],
]
const PODCAST = [
  ['daily_max', 'daily_max', num(1, 50)],
  ['min_subscribers', 'min_subscribers', num(0, 10000000)],
  ['max_subscribers', 'max_subscribers', num(1, 10000000)],
  ['min_uploads_30d', 'min_uploads_30d', num(0, 60)],
  ['min_episode_minutes', 'min_episode_minutes', num(1, 600)],
  ['searches_per_run', 'searches_per_run', num(1, 90)],
  ['follow_up_days', 'follow_up_days', days],
  ['draft_dms', 'draft_dms', bool],
  ['autopilot', 'autopilot', v => (['manual', 'auto'].includes(v) ? v : undefined)],
  ['sheet_url', 'sheet_url', v => (typeof v === 'string' ? v.trim() : undefined)],
  ['added_by', 'added_by', text],
]

const applied = []
const apply = (saved, list, prefix) => {
  for (const [from, to, rule] of list) {
    if (saved[from] === undefined || saved[from] === null || !(to in cfg)) continue
    const value = rule(saved[from])
    if (value === undefined) continue
    cfg[to] = value
    applied.push(prefix + from)
  }
}
apply(valueOf('outreach'), SHARED, '')
apply(valueOf('podcast'), PODCAST, 'podcast.')

const base = $('Config').first().json
if (cfg.send_window_start !== undefined && Number(cfg.send_window_start) >= Number(cfg.send_window_end)) {
  cfg.send_window_start = base.send_window_start
  cfg.send_window_end = base.send_window_end
}
if (cfg.min_subscribers !== undefined && Number(cfg.min_subscribers) >= Number(cfg.max_subscribers)) {
  cfg.min_subscribers = base.min_subscribers
  cfg.max_subscribers = base.max_subscribers
}
cfg.settings_applied = applied
return [{ json: cfg }]
